+                            keep_on_cpu: false,
+                        },
+                    ),
+                },
+                "monotonic_id": MmFieldElem {
+                    data: Some(
+                        Int(
+                            0,
+                        ),
+                    ),
+                    field: Batched(
+                        MmBatchedField {
+                            keep_on_cpu: false,
+                        },
+                    ),
+                },
+                "signature": MmFieldElem {
+                    data: Some(
+                        List(
+                            [],
+                        ),
+                    ),
+                    field: Batched(
+                        MmBatchedField {
+                            keep_on_cpu: false,
+                        },
+                    ),
+                },
+            }"#]]
+        .assert_eq(&format!("{redacted:#?}"));
