+            panic!("monotonic_id must be an int");
+        };
+        assert_eq!(*actual_address, address);
+        assert_eq!(*actual_id, monotonic_id);
+
+        let Some(MmKwargValue::List(signature)) = item["signature"].data.as_ref() else {
+            panic!("signature must be a list");
+        };
